using System;using System.IO;using System.Text;using System.Security.Cryptography;
public static class AudioVolume {
 // Cache a scaled PCM file so volume stays local to this game, with unchanged timestamps.
 public static string Prepare(string source,int volume,string root){volume=Math.Max(0,Math.Min(100,volume));if(volume==100||!source.EndsWith(".wav",StringComparison.OrdinalIgnoreCase))return source;try{var info=new FileInfo(source);string key;using(var hash=SHA256.Create())key=BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(source+"|"+info.Length+"|"+info.LastWriteTimeUtc.Ticks+"|"+volume))).Replace("-","");string folder=Path.Combine(root,".audio-cache");string target=Path.Combine(folder,key.Substring(0,8).ToLowerInvariant()+".wav");if(File.Exists(target))return target;using(var input=File.OpenRead(source))using(var reader=new BinaryReader(input)){if(new string(reader.ReadChars(4))!="RIFF")return source;reader.ReadInt32();if(new string(reader.ReadChars(4))!="WAVE")return source;int format=0,bits=0;long offset=0;uint bytes=0;while(input.Position+8<=input.Length){string chunk=new string(reader.ReadChars(4));uint size=reader.ReadUInt32();long end=input.Position+size;if(end>input.Length)return source;if(chunk=="fmt "&&size>=16){format=reader.ReadUInt16();reader.ReadUInt16();reader.ReadInt32();reader.ReadInt32();reader.ReadUInt16();bits=reader.ReadUInt16();}if(chunk=="data"){offset=input.Position;bytes=size;break;}input.Position=end+(size%2);}if(format!=1||bits!=16||offset==0)return source;Directory.CreateDirectory(folder);using(var output=File.Create(target)){input.Position=0;byte[] buffer=new byte[32768];long remaining=offset;while(remaining>0){int n=input.Read(buffer,0,(int)Math.Min(buffer.Length,remaining));output.Write(buffer,0,n);remaining-=n;}remaining=bytes;while(remaining>0){int n=input.Read(buffer,0,(int)Math.Min(buffer.Length,remaining));if(n==0)break;for(int i=0;i+1<n;i+=2){short sample=(short)(buffer[i]|buffer[i+1]<<8);short scaled=(short)(sample*volume/100);buffer[i]=(byte)(scaled&255);buffer[i+1]=(byte)((scaled>>8)&255);}output.Write(buffer,0,n);remaining-=n;}input.CopyTo(output);}}return target;}catch{return source;}}
}

